    Bug 1917179 - Tweak nsMsgOfflineImapOperation::SetSrcMessageKey() so it doesn't corrupt m_messageKey. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D221291

diff --git a/mailnews/db/msgdb/src/nsMsgOfflineImapOperation.cpp b/mailnews/db/msgdb/src/nsMsgOfflineImapOperation.cpp
index 9ece3ade36e..ff57e73db24 100644
--- a/mailnews/db/msgdb/src/nsMsgOfflineImapOperation.cpp
+++ b/mailnews/db/msgdb/src/nsMsgOfflineImapOperation.cpp
@@ -122,8 +122,9 @@ NS_IMETHODIMP nsMsgOfflineImapOperation::GetSrcMessageKey(

 NS_IMETHODIMP nsMsgOfflineImapOperation::SetSrcMessageKey(
     nsMsgKey aMessageKey) {
-  m_messageKey = aMessageKey;
-  return m_mdb->SetUint32Property(m_mdbRow, PROP_SRC_MESSAGE_KEY, m_messageKey);
+  m_sourceMessageKey = aMessageKey;
+  return m_mdb->SetUint32Property(m_mdbRow, PROP_SRC_MESSAGE_KEY,
+                                  m_sourceMessageKey);
 }

